WITH base AS (SELECT *, DATE_TRUNC('month', opened_date) AS opened_date_period, COALESCE(store_name, 'Unknown') AS store_name_filled FROM stores WHERE opened_date >= TO_DATE('2024-03-05') AND sqft = 11867) SELECT *, MAX(sqft) OVER (ORDER BY CAST(opened_date_period AS BIGINT) RANGE BETWEEN 604800 PRECEDING AND CURRENT ROW) AS sqft_max_7d, AVG(sqft) OVER (PARTITION BY region, city ORDER BY CAST(opened_date_period AS BIGINT) RANGE BETWEEN 604800 PRECEDING AND CURRENT ROW) AS sqft_avg_7d FROM base;
